select
c.*,
u.name assignName
from clue c
left join user u on c.user_id = u.id

    c.status in (1,2,3)

        and c.id = #{req.clueId}


        and c.phone like CONCAT('%', #{req.phone}, '%')


        and c.status = #{req.status}


        and c.channel = #{req.channel}


        and u.name like CONCAT('%', #{req.assignName}, '%')



        and c.user_id = #{userId}


order by c.id desc

select c.*, a.name activityName from clue c left join activity a on c.activity_id = a.id
c.status = 4
and c.id = #{req.clueId}
and c.phone like CONCAT('%', #{req.phone}, '%')
and c.channel = #{req.channel}
order by c.id desc
